package com.steven.assets.service.srpp.settings;
import com.fasterxml.jackson.databind.JsonNode;
import com.steven.assets.dto.SrppClaudeAuthDto;
import org.springframework.stereotype.Component;
import org.springframework.beans.factory.annotation.*;
import java.net.*;import java.net.http.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;import java.io.*;import java.nio.ByteBuffer;import java.util.concurrent.*;
@Component public final class SrppClaudeAuthLocal implements SrppClaudeAuthPort {
 private final URI base;private final Path token;private final HttpClient client;
 @Autowired public SrppClaudeAuthLocal(@Value("${srpp.settings.ai-token-file:/run/secrets/srpp_local_ai_token}")String token){this(URI.create("http://host.docker.internal:8766"),Path.of(token));}
 SrppClaudeAuthLocal(URI base,Path token){this.base=base;this.token=token;client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).proxy(new ProxySelector(){public List<Proxy>select(URI u){return List.of(Proxy.NO_PROXY);}public void connectFailed(URI u,SocketAddress a,IOException e){}}).build();}
 public JsonNode call(String action,JsonNode body){if(!Set.of("state","start","status","complete","cancel").contains(action))throw new SrppClaudeAuthProblem(400,"AI_INVALID_REQUEST");try{if(!Files.isRegularFile(token)||Files.size(token)>1024)throw new IOException();String secret=Files.readString(token).strip();if(!secret.matches("[A-Za-z0-9_-]{32,256}"))throw new IOException();byte[] encoded=SrppClaudeAuthDto.JSON.writeValueAsBytes(body);if(encoded.length>16384)throw new IOException();HttpRequest req=HttpRequest.newBuilder(base.resolve("/auth/claude/"+action)).timeout(Duration.ofSeconds(12)).header("Authorization","Bearer "+secret).header("Content-Type","application/json").header("Accept","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(encoded)).build();HttpResponse<byte[]> response=client.send(req,info->new LimitedBody());if(!response.headers().firstValue("Content-Type").orElse("").toLowerCase(Locale.ROOT).startsWith("application/json"))throw new IOException();JsonNode n=SrppClaudeAuthDto.parse(new String(response.body(),StandardCharsets.UTF_8));if(response.statusCode()!=200){SrppClaudeAuthDto.keys(n,"code","message","execution");if(!n.path("execution").isNull())throw new IOException();String code=SrppClaudeAuthDto.safe(SrppClaudeAuthDto.text(n,"code"));int status=switch(code){case "AUTH_BUSY","AI_AUTH_IN_PROGRESS"->409;case "AUTH_INVALID_CODE","AI_INVALID_REQUEST","AI_INVALID_SELECTION"->400;case "AUTH_SESSION_NOT_FOUND"->404;case "AUTH_TIMEOUT"->408;default->503;};throw new SrppClaudeAuthProblem(status,code);}return n;}catch(SrppClaudeAuthProblem e){throw e;}catch(HttpTimeoutException e){throw new SrppClaudeAuthProblem(504,"AUTH_TIMEOUT");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new SrppClaudeAuthProblem(503,"AUTH_FAILED");}catch(Exception e){throw new SrppClaudeAuthProblem(503,"AUTH_FAILED");}}
 private static final class LimitedBody implements HttpResponse.BodySubscriber<byte[]>{final CompletableFuture<byte[]> future=new CompletableFuture<>();final ByteArrayOutputStream bytes=new ByteArrayOutputStream();Flow.Subscription subscription;public CompletionStage<byte[]>getBody(){return future;}public void onSubscribe(Flow.Subscription s){subscription=s;s.request(1);}public void onNext(List<ByteBuffer>buffers){for(ByteBuffer b:buffers){if(bytes.size()+b.remaining()>16384){subscription.cancel();future.completeExceptionally(new IOException("Authentication response unavailable"));return;}byte[] p=new byte[b.remaining()];b.get(p);bytes.writeBytes(p);}subscription.request(1);}public void onError(Throwable e){future.completeExceptionally(new IOException("Authentication response unavailable"));}public void onComplete(){future.complete(bytes.toByteArray());}}
}
